tool_input.command:
$main='D:\repository\苏州市房地产监测V3'; $wt='D:\repository\苏州市房地产监测V3-wt-bug-6363'; $wtSub="$wt\zhi2-web-admin"
$mainSub="$main\zhi2-web-admin"
Write-Host "main sub node_modules exists: $(Test-Path "$mainSub\node_modules")"
Write-Host "wt node_modules exists: $(Test-Path "$wt\node_modules")"
# Create junctions to reuse main repo node_modules (offline build)
if (-not (Test-Path "$wt\node_modules")) {
  New-Item -ItemType Junction -Path "$wt\node_modules" -Target "$main\node_modules" -Force | Out-Null
  Write-Host 'junction: wt/node_modules -> main/node_modules'
} else { Write-Host 'wt/node_modules already present' }
if (-not (Test-Path "$wtSub\node_modules")) {
  New-Item -ItemType Junction -Path "$wtSub\node_modules" -Target "$mainSub\node_modules" -Force | Out-Null
  Write-Host 'junction: wt/zhi2-web-admin/node_modules -> main/zhi2-web-admin/node_modules'
} else { Write-Host 'wt sub node_modules already present' }
Write-Host "verify: $((Test-Path "$wt\node_modules") -and (Test-Path "$wtSub\node_modules"))"
